const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Amistad Reservoir centroid (approximate location obtained from Google Maps)
  const reservoir_point = ee.Geometry.Point(-101.07, 29.47);
  // Define a buffer around the point to cover the reservoir area
  const geometry = reservoir_point.buffer(30000); // 30 km buffer to cover the reservoir

  const start_date_2016 = '2016-08-01';
  const end_date_2016 = '2016-08-31';

  // Address 'August 2024': Data for future dates is not available.
  // We will use the most recent August available, which is August 2023, as a proxy.
  // If no data is available for August 2023, it might indicate an issue.
  const start_date_current = '2023-08-01';
  const end_date_current = '2023-08-31';

  // 2. Data Acquisition & Check
  // Function to mask clouds for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitmask = 1 << 10;
    const cirrusBitmask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitmask).eq(0).and(
        qa.bitwiseAnd(cirrusBitmask).eq(0)
    );
    return image.updateMask(mask).divide(10000)
        .select('B.*') // Select only band data for further processing
        .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate MNDWI
  function addMNDWI(image) {
    // For Sentinel-2: Green (B3), SWIR1 (B11)
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // Collection for 2016
  let s2_2016 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(start_date_2016, end_date_2016)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter for less cloudy images
      .map(maskS2clouds)
      .map(addMNDWI);

  const size_2016 = await s2_2016.size().getInfo();
  if (size_2016 === 0) {
    console.log("No Sentinel-2 images found for August 2016.");
    console.log("C1"); // Empty Collection
    return;
  }
  let img_2016 = s2_2016.median();

  // Collection for "current" (August 2023)
  let s2_current = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(start_date_current, end_date_current)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
      .map(maskS2clouds)
      .map(addMNDWI);

  const size_current = await s2_current.size().getInfo();
  if (size_current === 0) {
    console.log("No Sentinel-2 images found for August 2023 (proxy for August 2024).");
    console.log("C1"); // Empty Collection
    return;
  }
  let img_current = s2_current.median();

  // 3. Processing (Calculate water extent)
  // Define MNDWI threshold for water (common threshold is > 0)
  const mndwi_threshold = 0;
  const scale = 30; // 30 meters for area calculation

  // 2016 Water Mask and Area
  const water_2016 = img_2016.select('MNDWI').gt(mndwi_threshold).selfMask();
  const pixel_count_2016 = await water_2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  if (pixel_count_2016 === 0 || pixel_count_2016 === null) {
    console.log(`2016 Images: ${size_2016}`);
    console.log(`2023 Images: ${size_current}`);
    console.log("No valid water pixels found for 2016 after masking and MNDWI calculation.");
    console.log("C2"); // No Valid Pixels
    return;
  }
  const area_2016_sqm = pixel_count_2016 * scale * scale; // Area in square meters

  // Current (2023) Water Mask and Area
  const water_current = img_current.select('MNDWI').gt(mndwi_threshold).selfMask();
  const pixel_count_current = await water_current.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  if (pixel_count_current === 0 || pixel_count_current === null) {
    console.log(`2016 Images: ${size_2016} (Val Pixels: ${pixel_count_2016})`);
    console.log(`2023 Images: ${size_current}`);
    console.log("No valid water pixels found for 2023 after masking and MNDWI calculation.");
    console.log("C2"); // No Valid Pixels
    return;
  }
  const area_current_sqm = pixel_count_current * scale * scale; // Area in square meters

  // Convert to square kilometers for readability
  const area_2016_sqkm = area_2016_sqm / 1e6;
  const area_current_sqkm = area_current_sqm / 1e6;

  // 4. Calculation and 5. Validation & Final Answer
  if (area_2016_sqkm === null || area_current_sqkm === null) {
    console.log(`2016 Area: ${area_2016_sqkm}`);
    console.log(`2023 Area: ${area_current_sqkm}`);
    console.log("Area calculation resulted in null values.");
    console.log("C3"); // Calculation Failure
    return;
  }

  console.log(`2016 Images: ${size_2016}`);
  console.log(`2023 Images (proxy for 2024): ${size_current}`);
  console.log(`2016 Water Extent: ${area_2016_sqkm.toFixed(2)} sq km (Val Pixels: ${pixel_count_2016})`);
  console.log(`2023 Water Extent: ${area_current_sqkm.toFixed(2)} sq km (Val Pixels: ${pixel_count_current})`);

  if (area_current_sqkm < area_2016_sqkm) {
    console.log("A"); // Yes, surface water extent decreased
  } else {
    console.log("B"); // No, surface water extent did not decrease (it stayed the same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
